  sourceCitations: input.sourceCitations,
  rows,
  failClosed: failClosedReasons.length > 0,
  failClosedReasons: unique(failClosedReasons),
};

return {
  ...withoutHash,
  receiptHash: receiptHash(withoutHash),
};

